@NativeHandleDiscarding
class ${:NodeName}: ${:NodeType} {
	required init() {
		Self.initializeClass()
		super.init()
	}
}

extension ${:NodeName} {
	static func initializeClass() {
		let className = StringName("\(${:NodeName}.self)")
		let classInfo = ClassInfo<${:NodeName}>(name: className)
	}
}
